    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    background = max(counts, key=counts.get)
    markers = [v for v in counts if v != background]
    if not markers:
        return [row[:] for row in grid]
    marker = max(markers, key=lambda v: counts[v])
    points = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == marker}
    if not points:
        return [row[:] for row in grid]

    # Select the strongest rectangular frame rather than allowing isolated
    # marker outliers to determine its bounds.
    rows = sorted({r for r, c in points})
    cols = sorted({c for r, c in points})
    best = None
    for i, top in enumerate(rows):
        for bottom in rows[i + 1:]:
            for j, left in enumerate(cols):
                for right in cols[j + 1:]:
                    top_n = sum((top, c) in points for c in range(left, right + 1))
                    bot_n = sum((bottom, c) in points for c in range(left, right + 1))
                    left_n = sum((r, left) in points for r in range(top, bottom + 1))
                    right_n = sum((r, right) in points for r in range(top, bottom + 1))
                    if min(top_n, bot_n, left_n, right_n) == 0:
                        continue
                    perimeter = top_n + bot_n + left_n + right_n
                    outside = sum(not (top <= r <= bottom and left <= c <= right)
                                  for r, c in points)
                    # A small outlier penalty separates the supported inner
                    # frame from sparse stray markers just beyond a side.
                    score = (perimeter - outside, perimeter, bottom-top, right-left)
                    if best is None or score > best[0]:
                        best = (score, top, bottom, left, right)

    out = [row[:] for row in grid]
    if best:
        _, top, bottom, left, right = best
        for c in range(left, right + 1):
            if grid[top][c] == background:
                out[top][c] = 2
            if grid[bottom][c] == background:
                out[bottom][c] = 2
        for r in range(top, bottom + 1):
            if grid[r][left] == background:
                out[r][left] = 2
            if grid[r][right] == background:
                out[r][right] = 2

    # Away from the selected frame, fill only a one-cell gap between aligned
    # clues. Longer sparse alignments are not sufficient evidence by themselves.
    for r in range(h):
        for c in range(w - 2):
            if grid[r][c] == marker and grid[r][c + 2] == marker and grid[r][c + 1] == background:
